// newTestMovieComment builds a minimal, valid models.Comment for a movie
// (Comment set, no SeasonsComments), matching what
// services/comments.addCommentForMovie passes to Store.AddComment (no
// Id/CreatedAt/UpdatedAt: those are generated by the store).
func newTestMovieComment(t *testing.T, titleId, userId, text string) models.Comment {
	t.Helper()
	return models.Comment{
		TitleId: titleId,
		UserId:  userId,
		Comment: &text,
	}
}

// newTestSeriesComment builds a models.Comment with the given season ->
// comment-text entries (Comment nil, SeasonsComments set), matching what
// services/comments.addCommentForTVSeries passes to Store.AddComment.
func newTestSeriesComment(t *testing.T, titleId, userId string, seasons map[string]string) models.Comment {
	t.Helper()
	now := time.Now().UTC().Truncate(time.Second)
	seasonsComments := make(models.SeasonsComments, len(seasons))
	for season, text := range seasons {
		seasonsComments[season] = models.SeasonCommentItem{
			Comment:   text,
			AddedAt:   now,
			UpdatedAt: now,
		}
	}
	return models.Comment{
		TitleId:         titleId,
		UserId:          userId,
		SeasonsComments: &seasonsComments,
	}
}

func TestStore_AddComment_GetCommentById_Movie(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	titleId := "tt-movie-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	comment := newTestMovieComment(t, titleId, userId, "great movie")

	added, err := s.AddComment(ctx, comment)
	require.NoError(t, err)
	require.NotEmpty(t, added.Id, "AddComment must generate an id")
	require.Equal(t, titleId, added.TitleId)
	require.Equal(t, userId, added.UserId)
	require.NotNil(t, added.Comment)
	require.Equal(t, "great movie", *added.Comment)
	require.Nil(t, added.SeasonsComments, "a movie comment (no seasons) must round-trip with a nil SeasonsComments map")
	require.WithinDuration(t, time.Now(), added.CreatedAt, 5*time.Second)
	require.WithinDuration(t, time.Now(), added.UpdatedAt, 5*time.Second)

	got, err := s.GetCommentById(ctx, added.Id, userId)
	require.NoError(t, err)
	require.Equal(t, added, got)
}

func TestStore_AddComment_GetCommentById_Series(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	titleId := "tt-series-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	comment := newTestSeriesComment(t, titleId, userId, map[string]string{
		"1": "season 1 was great",
		"2": "season 2 was better",
	})

	added, err := s.AddComment(ctx, comment)
	require.NoError(t, err)
	require.Nil(t, added.Comment, "a series comment must round-trip with a nil top-level Comment")
	require.NotNil(t, added.SeasonsComments, "a series comment with seasons must round-trip with a non-nil SeasonsComments map")
	require.Len(t, *added.SeasonsComments, 2)
	require.Equal(t, "season 1 was great", (*added.SeasonsComments)["1"].Comment)
	require.Equal(t, "season 2 was better", (*added.SeasonsComments)["2"].Comment)

	got, err := s.GetCommentById(ctx, added.Id, userId)
	require.NoError(t, err)
	require.Nil(t, got.Comment)
	require.NotNil(t, got.SeasonsComments)
	require.Len(t, *got.SeasonsComments, 2)
	require.Equal(t, (*added.SeasonsComments)["1"].Comment, (*got.SeasonsComments)["1"].Comment)
	require.Equal(t, (*added.SeasonsComments)["2"].Comment, (*got.SeasonsComments)["2"].Comment)
	require.WithinDuration(t, (*added.SeasonsComments)["1"].AddedAt, (*got.SeasonsComments)["1"].AddedAt, time.Second)
}

func TestStore_GetUserCommentByTitleId(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	titleId := "tt-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	added, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, "nice"))
	require.NoError(t, err)

	got, err := s.GetUserCommentByTitleId(ctx, titleId, userId)
	require.NoError(t, err)
	require.Equal(t, added, got)

	t.Run("not found", func(t *testing.T) {
		_, err := s.GetUserCommentByTitleId(ctx, "missing-title", "missing-user")
		require.ErrorIs(t, err, store.ErrRecordNotFound)
	})
}

