func TestStore_GetCommentsByTitleId_FiltersByUsersFromGroup(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	titleId := "tt-" + uuid.NewString()
	otherTitleId := "tt-other-" + uuid.NewString()

	c1, err := s.AddComment(ctx, newTestMovieComment(t, titleId, "user-1", "from user 1"))
	require.NoError(t, err)
	c2, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, "user-2", map[string]string{"1": "s1"}))
	require.NoError(t, err)
	// user-3 also comments on titleId, but is not part of the group being
	// queried, so it must be excluded from the result.
	_, err = s.AddComment(ctx, newTestMovieComment(t, titleId, "user-3", "excluded"))
	require.NoError(t, err)
	_, err = s.AddComment(ctx, newTestMovieComment(t, otherTitleId, "user-1", "different title"))
	require.NoError(t, err)

	got, err := s.GetCommentsByTitleId(ctx, titleId, []string{"user-1", "user-2"})
	require.NoError(t, err)
	require.Len(t, got, 2)

	byId := map[string]models.Comment{}
	for _, c := range got {
		byId[c.Id] = c
	}
	require.Contains(t, byId, c1.Id)
	require.Contains(t, byId, c2.Id)
	require.Nil(t, byId[c1.Id].SeasonsComments)
	require.NotNil(t, byId[c2.Id].SeasonsComments)
	require.Len(t, *byId[c2.Id].SeasonsComments, 1)

	empty, err := s.GetCommentsByTitleId(ctx, "no-such-title", []string{"user-1"})
	require.NoError(t, err)
	require.Equal(t, []models.Comment{}, empty)
}

func TestStore_DeleteComment(t *testing.T) {
	t.Run("deletes comment and cascades its seasons", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()
		added, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, userId, map[string]string{"1": "s1"}))
		require.NoError(t, err)

		count, err := s.DeleteComment(ctx, added.Id, userId)
		require.NoError(t, err)
		require.EqualValues(t, 1, count)

		_, err = s.GetCommentById(ctx, added.Id, userId)
		require.ErrorIs(t, err, store.ErrRecordNotFound)

		var seasonCount int
		err = s.pool.QueryRow(ctx, `SELECT count(*) FROM comment_seasons WHERE comment_id = $1`, added.Id).Scan(&seasonCount)
		require.NoError(t, err)
		require.Zero(t, seasonCount, "comment_seasons rows must cascade-delete with their parent comment")
	})

	t.Run("not found reports a zero count with no error", func(t *testing.T) {
		// mongodb.DeleteComment never maps a zero-affected delete to
		// store.ErrRecordNotFound; it just returns the (zero) count.
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		count, err := s.DeleteComment(ctx, "missing-comment", "missing-user")
		require.NoError(t, err)
		require.Zero(t, count)
	})
}

func TestAddComment_DuplicateUserTitle(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	titleId := "tt-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	comment := newTestMovieComment(t, titleId, userId, "first comment")

	// First AddComment should succeed
	added, err := s.AddComment(ctx, comment)
	require.NoError(t, err)
	require.NotEmpty(t, added.Id)

	// Second AddComment with same (user, title) pair should return ErrDuplicatedRecord
	duplicate := newTestMovieComment(t, titleId, userId, "second comment")
	_, err = s.AddComment(ctx, duplicate)
	require.ErrorIs(t, err, store.ErrDuplicatedRecord)
}
